        var wus = Math.Max(1e-4, F("WorldUnitScale", 0.1));
        var burley = (bool?)s["bEnableBurley"] ?? true;
        var cm = burley ? F("MeanFreePathDistance", 1.2) / wus : F("ScatterRadius", 1.2) * wus;
        return new SubsurfaceInfo
        {
            Profile = path.Split('/').Last().Split('.').Last(),
            Radius = burley ? Rgb("MeanFreePathColor") : Rgb("FalloffColor"),
            Scale = cm * 0.01,
